import { Group, PlaneGeometry, MeshBasicNodeMaterial, Color } from 'three/webgpu';
import { vec2, uv, mul, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import { createText } from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // --- Background plane ---
  const planeGeo = new PlaneGeometry(1.6, 1);
  const material = new MeshBasicNodeMaterial({
    color: new Color(config.colors?.surface ?? '#0b0b10'),
  });

  // Load the provided image texture
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Subtle grain via a procedural node (optional, enhances "engineered gradient")
  // We add a faint noise multiplied to the color
  const grainStrength = uniform(0.03);
  const u = uv();
  const noise = mul(
    Math.sin(mul(u.x, 120.0)).add(Math.cos(mul(u.y, 80.0)).mul(0.5)).add(0.5),
    0.5
  );
  const grainNode = mul(noise, grainStrength).add(1.0);
  // Multiply existing material color by grain node
  // Since MeshBasicNodeMaterial supports .colorNode = ...
  material.colorNode = mul(material.color, grainNode);

  const mesh = new mesh(planeGeo, material);
  group.add(mesh);

  // --- Text label ---
  const textItems = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = textItems.find(item => item.role === 'headline') || { text: 'Pricing 1' };
  const textObj = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: 0.34, // headline scale from spec
    color: config.colors?.paper ?? '#e8ecf2',
    align: 'center',
  });
  textObj.position.z = 0.02; // float just above the plane
  group.add(textObj);

  // --- Cleanup ---
  group.userData.cleanup = () => {
    // Dispose geometry
    planeGeo.dispose();
    // Dispose material
    material.dispose();
    // If texture was loaded, dispose it
    if (material.map) material.map.dispose();
    // Dispose text resources (fontAtlas might handle internally, but we can remove children)
    textObj.traverse(child => {
      if (child.isMesh) {
        child.geometry?.dispose();
        if (child.material) {
          child.material.dispose();
          if (child.material.map) child.material.map.dispose();
        }
      }
    });
    // No GSAP timelines to kill
  };

  // No primitives to apply

  return group;
}
